const cfg = $input.first().json || {};
const missing = [];

if (!cfg.github_token || String(cfg.github_token).trim().length < 20 || String(cfg.github_token).includes('REPLACE_')) {
  missing.push('KB_GITHUB_TOKEN');
}

const status = missing.length ? 'error' : 'ok';
const output = status === 'ok'
  ? 'KB Sync Agent: конфиг валиден, запускаю проверку и обновление changelog.'
  : `KB Sync Agent: отсутствует/некорректен конфиг: ${missing.join(', ')}. Добавьте env в n8n и повторите.`;

return [{
  json: {
    ...cfg,
    config_status: status,
    chat_id: String(cfg.telegram_chat_id || '7326497224'),
    output,
  },
}];

const cfg = $input.first().json || {};

async function getJson(ctx, url, headers = {}) {
  return await ctx.helpers.httpRequest({
    method: 'GET',
    url,
    headers,
    json: true,
  });
}

try {
  const api = String(cfg.github_api);
  const owner = String(cfg.github_owner);
  const repo = String(cfg.github_repo);
  const branch = String(cfg.github_branch);
  const kbDir = String(cfg.kb_dir);
  const changelogPath = String(cfg.changelog_path);
  const staleDays = Number(cfg.stale_days || 7);

  const ghHeaders = {
    Authorization: `Bearer ${cfg.github_token}`,
    Accept: 'application/vnd.github+json',
    'User-Agent': 'kb-sync-agent',
  };

  const repoBase = `${api}/repos/${owner}/${repo}`;
  const kbCommitsUrl = `${repoBase}/commits?sha=${encodeURIComponent(branch)}&path=${encodeURIComponent(kbDir)}&per_page=20`;
  const repoCommitsUrl = `${repoBase}/commits?sha=${encodeURIComponent(branch)}&per_page=5`;
  const changelogUrl = `${repoBase}/contents/${encodeURIComponent(changelogPath)}?ref=${encodeURIComponent(branch)}`;

  const [kbCommits, repoCommits, changelogMeta] = await Promise.all([
    getJson(this, kbCommitsUrl, ghHeaders),
    getJson(this, repoCommitsUrl, ghHeaders),
    getJson(this, changelogUrl, ghHeaders),
  ]);

  const now = new Date();
  const nowIso = now.toISOString();
  const markerDate = nowIso.slice(0, 10);

  let kbLastCommitAt = null;
  let kbIsStale = true;
  let kbLastFiles = [];

  if (Array.isArray(kbCommits) && kbCommits.length) {
    kbLastCommitAt = kbCommits[0]?.commit?.committer?.date || kbCommits[0]?.commit?.author?.date || null;
    if (kbLastCommitAt) {
      const diffMs = now.getTime() - new Date(kbLastCommitAt).getTime();
      const diffDays = diffMs / (1000 * 60 * 60 * 24);
      kbIsStale = diffDays > staleDays;
    }

    const firstSha = kbCommits[0]?.sha;
    if (firstSha) {
      try {
        const commitDetails = await getJson(this, `${repoBase}/commits/${firstSha}`, ghHeaders);
        kbLastFiles = (commitDetails.files || []).map((f) => f.filename).slice(0, 10);
      } catch (_) {
        kbLastFiles = [];
      }
    }
  }

  let n8nSummary = null;
  if (cfg.n8n_api_key && String(cfg.n8n_api_key).trim()) {
    try {
      const workflowsResp = await getJson(this, `${cfg.n8n_api_base}/workflows?limit=100`, {
        'X-N8N-API-KEY': String(cfg.n8n_api_key),
      });
      const items = workflowsResp?.data || [];
      n8nSummary = {
        total_workflows: items.length,
        active_workflows: items.filter((w) => !!w.active).length,
      };
    } catch (e) {
      n8nSummary = { error: e.message || 'n8n api failed' };
    }
  }

  const changelogText = Buffer.from(changelogMeta.content || '', 'base64').toString('utf8');

  const kbCommitsShort = (kbCommits || []).slice(0, 5).map((c) => ({
    sha: String(c.sha || '').slice(0, 7),
    date: c?.commit?.committer?.date || c?.commit?.author?.date || '',
    message: c?.commit?.message?.split('\n')[0] || '',
    url: c?.html_url || '',
  }));

  const repoCommitsShort = (repoCommits || []).slice(0, 5).map((c) => ({
    sha: String(c.sha || '').slice(0, 7),
    date: c?.commit?.committer?.date || c?.commit?.author?.date || '',
    message: c?.commit?.message?.split('\n')[0] || '',
    url: c?.html_url || '',
  }));

  return [{
    json: {
      ...cfg,
      collect_status: 'ok',
      now_utc: nowIso,
      marker_date: markerDate,
      kb_last_commit_at: kbLastCommitAt,
      kb_is_stale: kbIsStale,
      kb_last_files: kbLastFiles,
      kb_commits_short: kbCommitsShort,
      repo_commits_short: repoCommitsShort,
      changelog_sha: changelogMeta.sha,
      changelog_text: changelogText,
      n8n_summary: n8nSummary,
      chat_id: String(cfg.telegram_chat_id || '7326497224'),
    },
  }];
} catch (e) {
  return [{
    json: {
      ...cfg,
      collect_status: 'error',
      output: `KB Sync Agent: ошибка сбора данных: ${e.message || 'unknown'}`,
      chat_id: String(cfg.telegram_chat_id || '7326497224'),
    },
  }];
}

const j = $input.first().json || {};

if (j.collect_status !== 'ok') {
  return [{
    json: {
      ...j,
      update_action: 'skip',
      output: j.output || 'KB Sync Agent: пропуск обновления из-за ошибки сбора данных.',
    },
  }];
}

const marker = `<!-- KB_SYNC: ${j.marker_date} -->`;
const alreadyUpdatedToday = String(j.changelog_text || '').includes(marker);

const kbStatus = j.kb_is_stale ? 'STALE' : 'FRESH';
const kbFilesLine = (j.kb_last_files || []).length
  ? (j.kb_last_files || []).map((f) => `  - ${f}`).join('\n')
  : '  - (нет данных по файлам)';

const repoCommitsLines = (j.repo_commits_short || []).map((c) => `  - ${c.sha} | ${c.date} | ${c.message}`).join('\n');
const kbCommitsLines = (j.kb_commits_short || []).map((c) => `  - ${c.sha} | ${c.date} | ${c.message}`).join('\n');

const n8nLine = j.n8n_summary
  ? (j.n8n_summary.error
      ? `- n8n API: ${j.n8n_summary.error}`
      : `- n8n workflows: total=${j.n8n_summary.total_workflows}, active=${j.n8n_summary.active_workflows}`)
  : '- n8n API: пропущено (нет N8N_PUBLIC_API_KEY)';

const section = [
  '',
  `### ${j.now_utc} — KB Sync Agent`,
  `- KB freshness: ${kbStatus} (last commit: ${j.kb_last_commit_at || 'n/a'}, threshold=${j.stale_days}d)`,
  n8nLine,
  '- Последние коммиты по KB:',
  kbCommitsLines || '  - (нет данных)',
  '- Файлы в последнем KB-коммите:',
  kbFilesLine,
  '- Последние коммиты репозитория:',
  repoCommitsLines || '  - (нет данных)',
  marker,
  ''
].join('\n');

if (alreadyUpdatedToday) {
  const output = `KB Sync Agent: запись за ${j.marker_date} уже есть. Freshness=${kbStatus}.`;
  return [{
    json: {
      ...j,
      update_action: 'skip',
      output,
    },
  }];
}

const updatedText = `${j.changelog_text}\n${section}`.trim() + '\n';
const contentB64 = Buffer.from(updatedText, 'utf8').toString('base64');
const commitMessage = `chore(kb): автообновление changelog (${j.marker_date})`;

return [{
  json: {
    ...j,
    update_action: 'update',
    output: `KB Sync Agent: подготовлено обновление changelog. Freshness=${kbStatus}.`,
    changelog_updated_b64: contentB64,
    changelog_commit_message: commitMessage,
  },
}];

const j = $input.first().json || {};

try {
  const api = String(j.github_api);
  const owner = String(j.github_owner);
  const repo = String(j.github_repo);
  const repoBase = `${api}/repos/${owner}/${repo}`;

  const headers = {
    Authorization: `Bearer ${j.github_token}`,
    Accept: 'application/vnd.github+json',
    'User-Agent': 'kb-sync-agent',
    'Content-Type': 'application/json',
  };

  const body = {
    message: String(j.changelog_commit_message || 'chore(kb): auto update changelog'),
    content: String(j.changelog_updated_b64 || ''),
    sha: String(j.changelog_sha || ''),
    branch: String(j.github_branch || 'main'),
  };

  const res = await this.helpers.httpRequest({
    method: 'PUT',
    url: `${repoBase}/contents/${encodeURIComponent(String(j.changelog_path))}`,
    headers,
    body,
    json: true,
  });

  const commitUrl = res?.commit?.html_url || '';
  return [{
    json: {
      ...j,
      push_status: 'ok',
      output: `KB Sync Agent: changelog обновлён успешно. ${commitUrl}`.trim(),
    },
  }];
} catch (e) {
  return [{
    json: {
      ...j,
      push_status: 'error',
      output: `KB Sync Agent: не удалось обновить changelog: ${e.message || 'unknown'}`
    },
  }];
}

